      "Darsliklardagi mazmun zamon o'zgarishlarini aks ettirmayotgani haqida tanqid bildirilgach, ularni qayta ko'rib chiqish yuzasidan muhokamalar o'tkazildi.",
      "Darslikdagi harflar bilimning hammasi emas, balki zamon kelajak avlodlarga yetkazmoqchi bo'lgan qadriyatlarning jamlanmasi va ayni paytda o'sha zamon cheklovlarining in'ikosidir."
