      "Suhbatdoshning savoliga samimiy javob berish ishonchni mustahkamlashning eng asosiy yo'lidir.",
      "Har qanday savolga javob berishga urinishdan ko'ra, ba'zan javob bermaslik jasorati so'zning qadrini saqlash yo'li bo'ladi."
