      "Bir necha yil davomida tayyorlangan loyiha bir necha bor inqirozlarni yengib o'tib, nihoyat samara bergach, jamoa a'zolari bir-birlarini quchoqlashdi.",
      "Necha marta yiqilsa ham qayta turadigan insonning bir necha og'iz so'zi son-sanoqsiz nutqlardan ham chuqurroq odamlar qalbini larzaga soladi."
