      "Yulduzlarning birgina gapi jamiyatga ko'rsatadigan ta'siri kuchaygani sari ulardan mas'uliyatni talab qiluvchi ovozlar ham balandroq yangramoqda.",
      "Yulduzning yaltiroq qiyofasi ortida ko'zga ko'rinmas mehnat va yolg'izlik borligini odamlar ko'pincha unutib qo'yishadi."
