      "U muvaffaqiyatsizlikni yashirmay, qayg'urish ham tiklanish jarayonining bir qismi ekanini o'ziga aytdi.",
      "Qayg'urish zaiflik belgisi emas, balki aziz narsasini yo'qotgan insonning eng tabiiy munosabatidir."
