      "Kino hozirgina boshlandi.",
      "Ertadan yozgi ta'til boshlanayotgani uchun xursandman.",
      "Shu haftadan boshlab yangi serial boshlanadi va ko'pchilik uni intiqlik bilan kutmoqda.",
      "Sanoat inqilobi bilan boshlangan urbanizatsiya odamlarning turmush tarzini tubdan o'zgartirib yubordi.",
