      "Koreyada birinchi marta uchrashgan odam bilan birinchi bo'lib \"annyonghaseyo\" deb salomlashish asosiy odob qoidasidir.",
      "O'qituvchimiz \"annyonghaseyo\" degan qisqa salomlashuvda ham suhbatdoshga tinchlik-xotirjamlik tilash ma'nosi mujassam ekanini tushuntirib berdilar.",
