      "Xona issiq bo'lgani uchun konditsionerni yoqdim.",
      "Konditsioner buzilib qolgani uchun kecha usta keldilar.",
      "Yozda konditsionerni juda past haroratga sozlab qo'ysangiz, sog'liq uchun yaxshi bo'lmasligi mumkin.",
      "Elektr energiyasi iste'moli keskin oshadigan yozning chillasida hukumat konditsionerdan foydalanishni kamaytirishni so'rab tez-tez murojaat qiladi.",
      "Konditsionersiz yozni o'tkazib bo'lmaydi, degan gaplar paydo bo'ladigan darajada iqlim o'zgarishi turmush tarzimizni o'zgartirib yubordi."
