      "U odamlar nimani xohlashini aniqlash uchun uzoq vaqt davomida bozor tadqiqotlarini olib borib kelgan.",
      "Chinakam nimani xohlayotganimizni bilmay chopaversak, muvaffaqiyatga erishganimizda ham bo'shliqni his qilishimiz oson."
