      "Jongno Joseon davridan beri Seulning markaziy ko'chasi bo'lib kelgan va hozir ham madaniyat va savdo uyg'unlashgan gavjum hududdir.",
      "Jongno ko'chalarining har bir torko'chasida qatlam-qatlam to'plangan yillar izi tez o'zgarayotgan shahar ichida o'zgarmas xotiralar xazinasiga o'xshaydi."
