      "Qog'ozga ismni yozamiz.",
      "Men qog'ozga rasm chizdim.",
      "Atrof-muhit uchun qog'ozni tejab ishlatish, ishlatib bo'lingan qog'ozni esa qayta ishlash qutisiga alohida tashlash kerak.",
