      "Stol tennisi o'yinchilari ko'z ochib-yumguncha u yoqdan-bu yoqqa uchadigan to'pni oldindan sezish uchun son-sanoqsiz takroriy mashg'ulotlardan o'tadilar.",
      "Kichkina bitta to'pni o'rtaga olib boriladigan stol tennisi o'yini oddiy ko'rinadi, ammo har bir ochkoda shiddatli psixologik kurash yashiringan."
