      "Tailandning an'anaviy taomlarida nordon, achchiq va shirin ta'mlar uyg'unlashgani uchun ular koreyslarning ta'biga ham juda mos keladi.",
      "Tailanddagi ibodatxonada yalangoyoq yurib, ro'para kelgan Buddha haykalining sokin tabassumi uning g'alayonli qalbini ancha tinchlantirdi."
