      "Avstraliya keng qit'asi va o'ziga xos ekotizimi bilan mashhur bo'lib, atrof-muhitni muhofaza qilishga katta e'tibor qaratiladigan mamlakatdir.",
      "Avstraliyaning cheksiz yoyilgan qizg'ish yerlari va musaffo osmoni ostida tursangiz, tabiatning ulug'vorligi qarshisida beixtiyor kamtar bo'lib qolasiz."
