      "Qora choyga sut va shakar qo'shilsa, ta'mi yumshoqroq bo'ladi va sovuq kunlarda tanani isitadi.",
      "Angliyada tushdan keyin qora choy va yengil gazaklar bilan o'tkaziladigan choy vaqti alohida turmush madaniyati sifatida qaror topgan.",
